


SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;


COMMENT ON SCHEMA "public" IS 'standard public schema';



CREATE EXTENSION IF NOT EXISTS "pg_net" WITH SCHEMA "public";






CREATE EXTENSION IF NOT EXISTS "pgsodium";






CREATE EXTENSION IF NOT EXISTS "pg_graphql" WITH SCHEMA "graphql";






CREATE EXTENSION IF NOT EXISTS "pg_stat_statements" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "pgcrypto" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "postgis" WITH SCHEMA "public";






CREATE EXTENSION IF NOT EXISTS "supabase_vault" WITH SCHEMA "vault";






CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA "extensions";






CREATE OR REPLACE FUNCTION "public"."auto_approve_top_pro_video"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  is_top BOOLEAN;
BEGIN
  SELECT is_top_pro INTO is_top FROM public.users WHERE id = NEW.pro_id;
  IF is_top = true THEN
    NEW.status = 'approved';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."auto_approve_top_pro_video"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_flag_video"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.flag_count >= 3 AND NEW.status != 'flagged' THEN NEW.status := 'flagged'; END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."auto_flag_video"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_booking_atomic"("p_client_id" "uuid", "p_slot_id" "uuid", "p_service_id" "uuid", "p_promo_code_id" "uuid" DEFAULT NULL::"uuid", "p_booking_code" "text" DEFAULT 'SPT-00000000'::"text") RETURNS json
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_slot time_slots%ROWTYPE;
    v_service services%ROWTYPE;
    v_discount DECIMAL DEFAULT 0;
    v_total DECIMAL;
    v_deposit DECIMAL;
    v_booking_id UUID;
BEGIN
    SELECT * INTO v_slot
    FROM time_slots
    WHERE id = p_slot_id
    FOR UPDATE NOWAIT;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'slot_unavailable';
    END IF;

    IF NOT v_slot.is_available THEN
        RAISE EXCEPTION 'slot_unavailable';
    END IF;

    SELECT * INTO v_service FROM services WHERE id = p_service_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'service_not_found';
    END IF;

    IF p_promo_code_id IS NOT NULL THEN
        SELECT COALESCE(
            CASE discount_type
                WHEN 'percentage' THEN v_service.price * discount_value / 100
                WHEN 'fixed' THEN discount_value
                ELSE 0
            END, 0
        ) INTO v_discount
        FROM promo_codes
        WHERE id = p_promo_code_id
          AND is_active = true
          AND (expires_at IS NULL OR expires_at > NOW())
          AND (max_uses IS NULL OR uses_count < max_uses);

        IF FOUND AND p_promo_code_id IS NOT NULL THEN
            UPDATE promo_codes SET uses_count = uses_count + 1 WHERE id = p_promo_code_id;
        END IF;
    END IF;

    v_total := GREATEST(v_service.price - v_discount, 0);
    v_deposit := ROUND(v_total * 0.30, 2);

    UPDATE time_slots
    SET is_available = false, locked_by = p_client_id
    WHERE id = p_slot_id;

    INSERT INTO bookings (
        client_id, pro_id, service_id, time_slot_id,
        status, total_amount, deposit_amount, currency,
        booking_code, promo_code_id
    ) VALUES (
        p_client_id, v_slot.pro_id, p_service_id, p_slot_id,
        'pending_payment', v_total, v_deposit, 'CAD',
        p_booking_code, p_promo_code_id
    )
    RETURNING id INTO v_booking_id;

    RETURN json_build_object(
        'booking_id', v_booking_id,
        'booking_code', p_booking_code,
        'total_amount', v_total,
        'deposit_amount', v_deposit
    );
END;
$$;


ALTER FUNCTION "public"."create_booking_atomic"("p_client_id" "uuid", "p_slot_id" "uuid", "p_service_id" "uuid", "p_promo_code_id" "uuid", "p_booking_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."decrypt_social_token"("p_ciphertext" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  v_key bytea;
  v_parts text[];
  v_nonce bytea;
  v_cipher bytea;
  v_plain bytea;
begin
  v_parts := string_to_array(p_ciphertext, ':');
  if array_length(v_parts, 1) != 2 then
    return null;
  end if;
  v_key := pgsodium.crypto_generichash(
    convert_to(coalesce(current_setting('app.settings.oauth_crypto_key', true), 'spotbook-default-key'), 'utf8'),
    32
  );
  v_nonce := decode(v_parts[1], 'hex');
  v_cipher := decode(v_parts[2], 'hex');
  v_plain := pgsodium.crypto_secretbox_open(v_cipher, v_nonce, v_key);
  return convert_from(v_plain, 'utf8');
exception when others then
  return null;
end;
$$;


ALTER FUNCTION "public"."decrypt_social_token"("p_ciphertext" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."decrypt_social_token"("p_encrypted_base64" "text", "p_nonce_hex" "text", "p_key_hex" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_key BYTEA;
    v_nonce BYTEA;
    v_encrypted BYTEA;
    v_decrypted BYTEA;
BEGIN
    v_key       := decode(p_key_hex, 'hex');
    v_nonce     := decode(p_nonce_hex, 'hex');
    v_encrypted := decode(p_encrypted_base64, 'base64');
    v_decrypted := decrypt_iv(v_encrypted, v_key, v_nonce, 'aes-cbc/pad:pkcs');
    RETURN convert_from(v_decrypted, 'UTF8');
END;
$$;


ALTER FUNCTION "public"."decrypt_social_token"("p_encrypted_base64" "text", "p_nonce_hex" "text", "p_key_hex" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."encrypt_social_token"("p_token" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  v_key bytea;
  v_nonce bytea;
  v_cipher bytea;
begin
  v_key := pgsodium.crypto_generichash(
    convert_to(coalesce(current_setting('app.settings.oauth_crypto_key', true), 'spotbook-default-key'), 'utf8'),
    32
  );
  v_nonce := pgsodium.randombytes_buf(24);
  v_cipher := pgsodium.crypto_secretbox(convert_to(p_token, 'utf8'), v_nonce, v_key);
  return encode(v_nonce, 'hex') || ':' || encode(v_cipher, 'hex');
end;
$$;


ALTER FUNCTION "public"."encrypt_social_token"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."encrypt_social_token"("p_token" "text", "p_nonce_hex" "text", "p_key_hex" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_key BYTEA;
    v_nonce BYTEA;
    v_data BYTEA;
    v_encrypted BYTEA;
BEGIN
    v_key   := decode(p_key_hex, 'hex');
    v_nonce := decode(p_nonce_hex, 'hex');
    v_data  := convert_to(p_token, 'UTF8');
    v_encrypted := encrypt_iv(v_data, v_key, v_nonce, 'aes-cbc/pad:pkcs');
    RETURN encode(v_encrypted, 'base64');
END;
$$;


ALTER FUNCTION "public"."encrypt_social_token"("p_token" "text", "p_nonce_hex" "text", "p_key_hex" "text") OWNER TO "postgres";


