CREATE OR REPLACE FUNCTION "public"."fire_send_push_notification"("p_user_id" "uuid", "p_title" "text", "p_body" "text", "p_type" "text", "p_data" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_url text;
  v_key text;
  v_body jsonb;
BEGIN
  BEGIN
    v_url := NULLIF(current_setting('app.settings.push_function_url', true), '');
    v_key := NULLIF(current_setting('app.settings.service_role_key', true), '');
  EXCEPTION
    WHEN undefined_object THEN
      v_url := NULL;
      v_key := NULL;
  END;

  IF v_url IS NULL OR v_key IS NULL THEN
    RAISE LOG 'fire_send_push_notification: skip (set app.settings.push_function_url and app.settings.service_role_key)';
    RETURN;
  END IF;

  v_body := jsonb_build_object(
    'userId', p_user_id::text,
    'title', p_title,
    'body', p_body,
    'type', p_type,
    'data', COALESCE(p_data, '{}'::jsonb)
  );

  PERFORM net.http_post(
    url := v_url,
    body := v_body,
    params := '{}'::jsonb,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_key
    ),
    timeout_milliseconds := 8000
  );
END;
$$;


ALTER FUNCTION "public"."fire_send_push_notification"("p_user_id" "uuid", "p_title" "text", "p_body" "text", "p_type" "text", "p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_or_create_inquiry"("p_client_id" "uuid", "p_pro_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_conv_id uuid;
  v_blocked boolean;
BEGIN
  -- Vérifier que le client n'est pas bloqué par le pro (et vice versa)
  SELECT EXISTS (
    SELECT 1 FROM blocks
    WHERE (blocker_id = p_pro_id AND blocked_id = p_client_id)
       OR (blocker_id = p_client_id AND blocked_id = p_pro_id)
  ) INTO v_blocked;

  IF v_blocked THEN
    RAISE EXCEPTION 'blocked' USING ERRCODE = 'P0403';
  END IF;

  -- Vérifier que le pro existe
  IF NOT EXISTS (SELECT 1 FROM profiles_pro WHERE id = p_pro_id) THEN
    RAISE EXCEPTION 'pro_not_found' USING ERRCODE = 'P0404';
  END IF;

  -- Chercher une conversation inquiry existante
  SELECT id INTO v_conv_id
  FROM conversations
  WHERE client_id = p_client_id
    AND pro_id = p_pro_id
    AND type = 'inquiry';

  -- Si elle n'existe pas, la créer
  IF v_conv_id IS NULL THEN
    INSERT INTO conversations (client_id, pro_id, type)
    VALUES (p_client_id, p_pro_id, 'inquiry')
    ON CONFLICT (client_id, pro_id) WHERE type = 'inquiry'
    DO UPDATE SET created_at = conversations.created_at -- no-op, retourne l'existante
    RETURNING id INTO v_conv_id;
  END IF;

  RETURN v_conv_id;
END;
$$;


ALTER FUNCTION "public"."get_or_create_inquiry"("p_client_id" "uuid", "p_pro_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_unread_counts"() RETURNS TABLE("unread_notifications" integer, "unread_messages" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    COALESCE((
      SELECT COUNT(*)::int FROM notifications
      WHERE user_id = auth.uid() AND is_read = false
    ), 0) AS unread_notifications,
    COALESCE((
      SELECT SUM(
        CASE
          WHEN c.client_id = auth.uid() THEN c.unread_count_client
          WHEN c.pro_id = auth.uid() THEN c.unread_count_pro
          ELSE 0
        END
      )::int
      FROM conversations c
      WHERE c.client_id = auth.uid() OR c.pro_id = auth.uid()
    ), 0) AS unread_messages;
END;
$$;


ALTER FUNCTION "public"."get_unread_counts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_pro_role_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Si le rôle change vers 'pro' et qu'il n'a pas encore de profil pro
  IF NEW.role = 'pro' AND (OLD.role IS NULL OR OLD.role <> 'pro') THEN
    INSERT INTO public.profiles_pro (id, business_name, category, is_public, search_visible)
    VALUES (
      NEW.id,
      COALESCE(NEW.full_name, 'Mon Business'),
      'Autre',
      true,
      true
    )
    ON CONFLICT (id) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_pro_role_change"() OWNER TO "postgres";


