CREATE OR REPLACE FUNCTION "public"."mark_messages_read"("p_conversation_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_client_id uuid;
  v_pro_id uuid;
  v_updated int;
BEGIN
  SELECT client_id, pro_id INTO v_client_id, v_pro_id
  FROM conversations WHERE id = p_conversation_id;

  -- Vérifier que l'appelant est participant
  IF auth.uid() != v_client_id AND auth.uid() != v_pro_id THEN
    RAISE EXCEPTION 'not_participant' USING ERRCODE = 'P0403';
  END IF;

  -- Marquer comme lus tous les messages NON envoyés par l'appelant
  UPDATE messages
  SET is_read = true, read_at = now()
  WHERE conversation_id = p_conversation_id
    AND sender_id != auth.uid()
    AND is_read = false;

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  -- Remettre à zéro le compteur de l'appelant
  IF auth.uid() = v_client_id THEN
    UPDATE conversations SET unread_count_client = 0
    WHERE id = p_conversation_id;
  ELSE
    UPDATE conversations SET unread_count_pro = 0
    WHERE id = p_conversation_id;
  END IF;

  RETURN v_updated;
END;
$$;


ALTER FUNCTION "public"."mark_messages_read"("p_conversation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rate_limit_consume"("p_scope" "text", "p_rate_key" "text", "p_bucket" bigint, "p_max" integer, "p_window_ms" bigint) RETURNS TABLE("allowed" boolean, "retry_in_minutes" integer, "remaining" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_now_ms bigint := (extract(epoch from clock_timestamp()) * 1000)::bigint;
  v_count int;
  v_expires timestamptz := to_timestamp(((p_bucket + 1) * p_window_ms) / 1000.0);
  v_mod bigint;
  v_retry numeric;
BEGIN
  IF p_scope NOT IN ('login', 'otp', 'payment') THEN
    allowed := false;
    retry_in_minutes := 0;
    remaining := 0;
    RETURN NEXT;
    RETURN;
  END IF;

  PERFORM pg_advisory_xact_lock(
    (hashtext(p_scope || chr(1) || p_rate_key || chr(1) || p_bucket::text))::bigint
  );

  SELECT c.hit_count INTO v_count
  FROM public.rate_limit_counters AS c
  WHERE c.scope = p_scope
    AND c.rate_key = p_rate_key
    AND c.bucket = p_bucket;

  IF FOUND THEN
    IF v_count >= p_max THEN
      v_mod := v_now_ms % p_window_ms;
      v_retry := ceil((p_window_ms - v_mod)::numeric / 60000);
      allowed := false;
      retry_in_minutes := GREATEST(1, v_retry::int);
      remaining := 0;
      RETURN NEXT;
      RETURN;
    END IF;

    UPDATE public.rate_limit_counters
    SET hit_count = hit_count + 1
    WHERE scope = p_scope
      AND rate_key = p_rate_key
      AND bucket = p_bucket;

    allowed := true;
    retry_in_minutes := 0;
    remaining := GREATEST(0, p_max - (v_count + 1));
    RETURN NEXT;
    RETURN;
  END IF;

  INSERT INTO public.rate_limit_counters (scope, rate_key, bucket, hit_count, expires_at)
  VALUES (p_scope, p_rate_key, p_bucket, 1, v_expires);

  allowed := true;
  retry_in_minutes := 0;
  remaining := GREATEST(0, p_max - 1);
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."rate_limit_consume"("p_scope" "text", "p_rate_key" "text", "p_bucket" bigint, "p_max" integer, "p_window_ms" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rotate_social_token_cipher"("p_ciphertext" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  v_plain text;
begin
  v_plain := public.decrypt_social_token(p_ciphertext);
  if v_plain is null then
    return p_ciphertext;
  end if;
  return public.encrypt_social_token(v_plain);
end;
$$;


ALTER FUNCTION "public"."rotate_social_token_cipher"("p_ciphertext" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_events_nearby"("p_lat" double precision DEFAULT NULL::double precision, "p_lng" double precision DEFAULT NULL::double precision, "p_radius_km" double precision DEFAULT 50, "p_query" "text" DEFAULT NULL::"text", "p_category" "text" DEFAULT NULL::"text", "p_date_from" timestamp with time zone DEFAULT "now"(), "p_date_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_limit" integer DEFAULT 30) RETURNS TABLE("id" "uuid", "title" "text", "description" "text", "cover_url" "text", "event_date" timestamp with time zone, "location" "text", "address" "text", "latitude" double precision, "longitude" double precision, "pro_id" "uuid", "pro_name" "text", "pro_avatar" "text", "pro_username" "text", "min_price" numeric, "max_price" numeric, "total_tickets" integer, "sold_tickets" integer, "distance_km" double precision)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    e.id,
    e.title,
    e.description,
    e.cover_url,
    e.event_date,
    e.location,
    e.address,
    -- Utilise les coordonnées de l'événement si dispo, sinon celles du pro
    COALESCE(e.latitude, u.latitude) AS latitude,
    COALESCE(e.longitude, u.longitude) AS longitude,
    e.pro_id,
    u.full_name AS pro_name,
    u.avatar_url AS pro_avatar,
    u.username AS pro_username,
    MIN(tt.price) AS min_price,
    MAX(tt.price) AS max_price,
    COALESCE(SUM(tt.quantity)::int, 0) AS total_tickets,
    COALESCE(SUM(tt.sold_count)::int, 0) AS sold_tickets,
    CASE
      WHEN p_lat IS NOT NULL AND p_lng IS NOT NULL
           AND COALESCE(e.latitude, u.latitude) IS NOT NULL
           AND COALESCE(e.longitude, u.longitude) IS NOT NULL
      THEN 6371 * acos(
        LEAST(1.0, GREATEST(-1.0,
          cos(radians(p_lat)) * cos(radians(COALESCE(e.latitude, u.latitude))) *
          cos(radians(COALESCE(e.longitude, u.longitude)) - radians(p_lng)) +
          sin(radians(p_lat)) * sin(radians(COALESCE(e.latitude, u.latitude)))
        ))
      )
      ELSE NULL
    END AS distance_km
  FROM events e
  JOIN users u ON u.id = e.pro_id
  LEFT JOIN ticket_types tt ON tt.event_id = e.id
  WHERE e.is_active = true
    AND e.event_date >= COALESCE(p_date_from, now())
    AND (p_date_to IS NULL OR e.event_date <= p_date_to)
    AND (p_query IS NULL OR (
      e.title ILIKE '%' || p_query || '%'
      OR e.description ILIKE '%' || p_query || '%'
      OR e.location ILIKE '%' || p_query || '%'
      OR e.address ILIKE '%' || p_query || '%'
    ))
    AND (p_category IS NULL OR EXISTS (
      SELECT 1 FROM profiles_pro pp WHERE pp.id = e.pro_id AND pp.category = p_category
    ))
  GROUP BY e.id, u.full_name, u.avatar_url, u.username, u.latitude, u.longitude
  HAVING (
    p_lat IS NULL OR p_lng IS NULL
    OR COALESCE(e.latitude, u.latitude) IS NULL
    OR 6371 * acos(
      LEAST(1.0, GREATEST(-1.0,
        cos(radians(p_lat)) * cos(radians(COALESCE(e.latitude, u.latitude))) *
        cos(radians(COALESCE(e.longitude, u.longitude)) - radians(p_lng)) +
        sin(radians(p_lat)) * sin(radians(COALESCE(e.latitude, u.latitude)))
      ))
    ) <= p_radius_km
  )
  ORDER BY
    CASE
      WHEN p_lat IS NOT NULL AND p_lng IS NOT NULL
           AND COALESCE(e.latitude, u.latitude) IS NOT NULL
      THEN 6371 * acos(
        LEAST(1.0, GREATEST(-1.0,
          cos(radians(p_lat)) * cos(radians(COALESCE(e.latitude, u.latitude))) *
          cos(radians(COALESCE(e.longitude, u.longitude)) - radians(p_lng)) +
          sin(radians(p_lat)) * sin(radians(COALESCE(e.latitude, u.latitude)))
        ))
      )
      ELSE 0
    END ASC,
    e.event_date ASC
  LIMIT LEAST(p_limit, 100);
END;
$$;


ALTER FUNCTION "public"."search_events_nearby"("p_lat" double precision, "p_lng" double precision, "p_radius_km" double precision, "p_query" "text", "p_category" "text", "p_date_from" timestamp with time zone, "p_date_to" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_providers_nearby"("p_lat" double precision DEFAULT NULL::double precision, "p_lng" double precision DEFAULT NULL::double precision, "p_radius_km" double precision DEFAULT 50, "p_query" "text" DEFAULT NULL::"text", "p_category" "text" DEFAULT NULL::"text", "p_min_rating" double precision DEFAULT 0, "p_limit" integer DEFAULT 30) RETURNS TABLE("id" "uuid", "business_name" "text", "category" "text", "average_rating" numeric, "review_count" integer, "full_name" "text", "avatar_url" "text", "city" "text", "username" "text", "distance_km" double precision, "latitude" double precision, "longitude" double precision)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH base AS (
    SELECT
      p.id AS pid,
      p.business_name AS pbusiness,
      p.category AS pcategory,
      p.average_rating AS pavg,
      p.review_count AS prcount,
      u.full_name AS ufullname,
      u.avatar_url AS uavatar,
      u.city AS ucity,
      u.username AS uusername,
      u.latitude AS ulat,
      u.longitude AS ulng,
      CASE
        WHEN p_lat IS NOT NULL AND p_lng IS NOT NULL
          AND u.latitude IS NOT NULL AND u.longitude IS NOT NULL
        THEN
          (6371.0 * acos(
            LEAST(1.0::double precision, GREATEST(-1.0::double precision,
              cos(radians(p_lat)) * cos(radians(u.latitude))
              * cos(radians(u.longitude) - radians(p_lng))
              + sin(radians(p_lat)) * sin(radians(u.latitude))
            ))
          ))
        ELSE NULL::double precision
      END AS dist
    FROM profiles_pro p
    INNER JOIN users u ON u.id = p.id
    WHERE u.role = 'pro'
      AND COALESCE(p.is_public, true) = true
      AND COALESCE(p.search_visible, true) = true
      AND COALESCE(p.average_rating, 0) >= COALESCE(p_min_rating, 0)
      AND (
        p_query IS NULL
        OR btrim(p_query) = ''
        OR p.business_name ILIKE '%' || p_query || '%'
        OR u.full_name ILIKE '%' || p_query || '%'
        OR u.city ILIKE '%' || p_query || '%'
        OR u.username ILIKE '%' || p_query || '%'
      )
      AND (
        p_category IS NULL
        OR btrim(p_category) = ''
        OR LOWER(TRIM(p.category)) = LOWER(TRIM(p_category))
      )
  ),
  filtered AS (
    SELECT *
    FROM base b
    WHERE b.dist IS NULL OR b.dist <= p_radius_km
  )
  SELECT
    f.pid AS id,
    f.pbusiness AS business_name,
    f.pcategory AS category,
    f.pavg AS average_rating,
    f.prcount AS review_count,
    f.ufullname AS full_name,
    f.uavatar AS avatar_url,
    f.ucity AS city,
    f.uusername AS username,
    f.dist AS distance_km,
    f.ulat AS latitude,
    f.ulng AS longitude
  FROM filtered f
  ORDER BY
    (f.dist IS NULL) ASC,
    f.dist ASC NULLS LAST,
    f.prcount DESC NULLS LAST,
    f.pavg DESC NULLS LAST
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 20), 1), 100);
$$;


ALTER FUNCTION "public"."search_providers_nearby"("p_lat" double precision, "p_lng" double precision, "p_radius_km" double precision, "p_query" "text", "p_category" "text", "p_min_rating" double precision, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tr_notify_new_booking_push"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  client_name text;
BEGIN
  SELECT COALESCE(full_name, 'Un client') INTO client_name
  FROM public.users WHERE id = NEW.client_id;

  PERFORM public.fire_send_push_notification(
    NEW.pro_id,
    'Nouvelle réservation',
    client_name || ' a réservé un rendez-vous.',
    'booking',
    jsonb_build_object(
      'bookingId', NEW.id::text,
      'route', '/pro/bookings'
    )
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."tr_notify_new_booking_push"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tr_notify_new_follower"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_follower_name text;
BEGIN
  SELECT COALESCE(full_name, username, 'Quelqu''un')
  INTO v_follower_name
  FROM users WHERE id = NEW.follower_id;

  -- Notification in-app
  INSERT INTO notifications (user_id, type, title, body, resource_id, data)
  VALUES (
    NEW.following_id,
    'follow',
    'Nouveau follower',
    v_follower_name || ' vous suit maintenant',
    NEW.follower_id::text,
    jsonb_build_object(
      'follower_id', NEW.follower_id::text,
      'route', '/pro/profile'
    )
  );

  -- Push notification
  PERFORM fire_send_push_notification(
    NEW.following_id,
    'Nouveau follower',
    v_follower_name || ' vous suit maintenant',
    'follow',
    jsonb_build_object(
      'follower_id', NEW.follower_id::text,
      'route', '/pro/profile'
    )
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."tr_notify_new_follower"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tr_notify_new_message_push"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  conv public.conversations%ROWTYPE;
  recipient uuid;
  preview text;
BEGIN
  SELECT * INTO conv FROM public.conversations WHERE id = NEW.conversation_id;
  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  IF NEW.sender_id = conv.client_id THEN
    recipient := conv.pro_id;
  ELSE
    recipient := conv.client_id;
  END IF;

  IF recipient IS NULL OR recipient = NEW.sender_id THEN
    RETURN NEW;
  END IF;

  preview := LEFT(COALESCE(NEW.content, '📷 Image'), 140);

  PERFORM public.fire_send_push_notification(
    recipient,
    'Nouveau message',
    preview,
    'message',
    jsonb_build_object(
      'conversationId', NEW.conversation_id::text,
      'route', '/client/messages'
    )
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."tr_notify_new_message_push"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tr_notify_review_response"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pro_name text;
BEGIN
  -- Seulement si pro_response vient d'être ajoutée
  IF NEW.pro_response IS NOT NULL AND OLD.pro_response IS NULL THEN
    SELECT COALESCE(pp.business_name, u.full_name, 'Le professionnel')
    INTO v_pro_name
    FROM profiles_pro pp
    JOIN users u ON u.id = pp.id
    WHERE pp.id = NEW.pro_id;

    INSERT INTO notifications (user_id, type, title, body, resource_id, data)
    VALUES (
      NEW.client_id,
      'review_response',
      'Réponse à votre avis',
      v_pro_name || ' a répondu à votre avis',
      NEW.id::text,
      jsonb_build_object(
        'review_id', NEW.id::text,
        'pro_id', NEW.pro_id::text,
        'route', '/client/bookings'
      )
    );

    PERFORM fire_send_push_notification(
      NEW.client_id,
      'Réponse à votre avis',
      v_pro_name || ' a répondu à votre avis',
      'review_response',
      jsonb_build_object('review_id', NEW.id::text, 'pro_id', NEW.pro_id::text)
    );

    -- Marquer le timestamp de réponse
    -- (fait dans le même UPDATE, pas besoin de re-UPDATE)
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."tr_notify_review_response"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tr_notify_ticket_sold_push"() RETURNS "trigger"
