CREATE OR REPLACE FUNCTION "public"."update_top_pro"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  UPDATE profiles_pro SET
    average_rating = (SELECT AVG(rating) FROM reviews WHERE pro_id = NEW.pro_id),
    review_count = (SELECT COUNT(*) FROM reviews WHERE pro_id = NEW.pro_id),
    is_top_pro = (
      (SELECT AVG(rating) FROM reviews WHERE pro_id = NEW.pro_id) >= 4.8
      AND (SELECT COUNT(*) FROM reviews WHERE pro_id = NEW.pro_id) >= 10
    )
  WHERE id = NEW.pro_id;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_top_pro"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_unread_count"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_client_id uuid;
  v_pro_id uuid;
BEGIN
  SELECT client_id, pro_id INTO v_client_id, v_pro_id
  FROM conversations WHERE id = NEW.conversation_id;

  IF v_client_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    -- Le message est envoyé : incrémenter le compteur de l'autre partie
    IF NEW.sender_id = v_client_id THEN
      UPDATE conversations SET unread_count_pro = unread_count_pro + 1
      WHERE id = NEW.conversation_id;
    ELSIF NEW.sender_id = v_pro_id THEN
      UPDATE conversations SET unread_count_client = unread_count_client + 1
      WHERE id = NEW.conversation_id;
    END IF;
  ELSIF TG_OP = 'UPDATE' AND NEW.is_read = true AND OLD.is_read = false THEN
    -- Le message est lu : décrémenter le compteur du lecteur
    IF NEW.sender_id = v_pro_id THEN
      -- Le client lit un message du pro
      UPDATE conversations SET unread_count_client = GREATEST(unread_count_client - 1, 0)
      WHERE id = NEW.conversation_id;
    ELSIF NEW.sender_id = v_client_id THEN
      -- Le pro lit un message du client
      UPDATE conversations SET unread_count_pro = GREATEST(unread_count_pro - 1, 0)
      WHERE id = NEW.conversation_id;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_unread_count"() OWNER TO "postgres";


