  WHERE ("r"."id" = "reviews"."id")))) AND (NOT ("client_id" IS DISTINCT FROM ( SELECT "r"."client_id"
   FROM "public"."reviews" "r"
  WHERE ("r"."id" = "reviews"."id")))) AND (NOT ("booking_id" IS DISTINCT FROM ( SELECT "r"."booking_id"
   FROM "public"."reviews" "r"
  WHERE ("r"."id" = "reviews"."id"))))));



CREATE POLICY "reviews_select_authenticated" ON "public"."reviews" FOR SELECT TO "authenticated" USING ((NOT "public"."is_blocked"("auth"."uid"(), "client_id")));



CREATE POLICY "reviews_update_as_client" ON "public"."reviews" FOR UPDATE TO "authenticated" USING (("auth"."uid"() = "client_id"));



